    gy = game.state.zones.get(f'graveyard_{p1.id}')
    if gy is not None and gcard.id not in gy.objects:
        gy.objects.append(gcard.id)
    game.state.active_player = p1.id
    game.emit(Event(type=EventType.PHASE_START, payload={'phase': "upkeep"}, source=None))
    _assert_emits(game, ['RETURN_TO_HAND', 'RETURN_FROM_GRAVEYARD', 'RETURN_TO_HAND_FROM_GRAVEYARD', 'BOUNCE'], "Wort, Boggart Auntie")

