def _run():
    strict = bool(os.environ.get("HYPERDRAFT_STRICT"))
    passed, failed, errored = [], [], []
    for fn in _ALL_TESTS:
        name = fn.__name__
        try:
            fn()
            passed.append(name)
        except AssertionError as e:
            failed.append((name, str(e)))
            if strict:
                print(f"FAIL  {name}")
                traceback.print_exc()
        except Exception as e:  # noqa: BLE001 — surface card-side errors
            errored.append((name, f"{type(e).__name__}: {e}"))
            if strict:
                print(f"ERROR {name}")
                traceback.print_exc()

    total = len(_ALL_TESTS)
    skipped = len(SKIPPED_CARDS)
    print("=" * 72)
    print(f"lorwyn_custom interceptor verification")
    print(f"  generated tests : {total}")
    print(f"  passed          : {len(passed)}")
    print(f"  failed          : {len(failed)}")
    print(f"  errored         : {len(errored)}")
    print(f"  skipped (struct): {skipped}")
    print("=" * 72)
    if failed:
        print("\nFAILED (text-named effect did not fire / wrong effect):")
        for n, msg in failed:
            print(f"  - {n}: {msg}")
    if errored:
        print("\nERRORED (card-side exception surfaced under strict mode):")
        for n, msg in errored:
            print(f"  - {n}: {msg}")
    return 0 if not failed and not errored else 1


if __name__ == "__main__":
    sys.exit(_run())
